/* ==========================================
   Pixel Roman Numeral Converter - Styles
   Cohesive 4-Color Retro Palette:
   1. Deep Ink Background: #181425
   2. Antique Parchment:   #fee761
   3. Warm Brick/Crimson:  #c23a4b
   4. Stone Slate Panel:   #262b44
   5. Soft White Highlight:#ffffff
   ========================================== */

:root {
  --bg-color: #181425;
  --card-bg: #262b44;
  --card-border: #0b0c15;
  --accent-gold: #fee761;
  --accent-crimson: #c23a4b;
  --accent-mint: #38b764;
  --text-main: #ffffff;
  --text-muted: #8b9bb4;
  --font-stack: 'Courier New', Courier, monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  background-image:
    linear-gradient(45deg, #141020 25%, transparent 25%),
    linear-gradient(-45deg, #141020 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #141020 75%),
    linear-gradient(-45deg, transparent 75%, #141020 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  color: var(--text-main);
  font-family: var(--font-stack);
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px 12px;
}

.card-container {
  width: 100%;
  max-width: 480px;
  display: flex;
  justify-content: center;
}

/* Pixel Card Container with Stepped Borders */
.pixel-card {
  width: 100%;
  background: var(--card-bg);
  border: 4px solid var(--card-border);
  box-shadow:
    0 0 0 4px var(--card-bg),
    0 0 0 8px var(--card-border),
    8px 8px 0 8px #00000088;
  padding: 24px 20px;
}

.card-header {
  text-align: center;
  margin-bottom: 24px;
  border-bottom: 4px dashed #3a4466;
  padding-bottom: 16px;
}

.header-badge {
  display: inline-block;
  background: #181425;
  color: var(--accent-gold);
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 2px;
  padding: 4px 10px;
  margin-bottom: 10px;
  border: 2px solid #3a4466;
}

.title {
  font-size: 28px;
  letter-spacing: 2px;
  color: var(--accent-gold);
  text-shadow: 3px 3px 0 #0b0c15;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 16px;
  color: var(--text-muted);
}

/* Form Field Controls */
.converter-body {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pixel-label {
  font-size: 16px;
  font-weight: bold;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.label-tag {
  font-size: 12px;
  background: var(--accent-gold);
  color: #181425;
  padding: 2px 6px;
  font-weight: 900;
  border: 2px solid var(--card-border);
}

.input-wrapper {
  position: relative;
}

input[type="number"],
input[type="text"] {
  width: 100%;
  font-family: var(--font-stack);
  font-size: 20px;
  font-weight: bold;
  padding: 10px 14px;
  color: #ffffff;
  background-color: #181425;
  border: 4px solid #3a4466;
  outline: none;
  box-shadow: inset 3px 3px 0 #0b0c15;
  transition: border-color 0.1s ease, box-shadow 0.1s ease;
}

input[type="number"]:hover,
input[type="text"]:hover {
  border-color: #5a6988;
}

input[type="number"]:focus,
input[type="text"]:focus {
  border-color: var(--accent-gold);
  box-shadow:
    inset 3px 3px 0 #0b0c15,
    0 0 0 3px #fee76144;
}

/* Remove number spinner arrows for consistent pixel look */
input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
input[type="number"] {
  -moz-appearance: textfield;
}

/* Live Display Box */
.live-preview {
  background: #181425;
  border: 3px solid #3a4466;
  padding: 10px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 48px;
  gap: 12px;
}

.preview-label {
  font-size: 14px;
  color: var(--text-muted);
}

.preview-value {
  font-size: 20px;
  font-weight: bold;
  color: var(--accent-mint);
  text-align: right;
  word-break: break-all;
}

.preview-value.invalid {
  color: var(--accent-crimson);
  text-shadow: 1px 1px 0 #000000;
}

.preview-value.empty {
  color: #4f5a72;
}

/* Pixel divider between fields */
.pixel-divider {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  color: #3a4466;
  font-size: 14px;
  margin: 4px 0;
}

/* Quick Reference Bar */
.quick-ref {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
  margin-top: 10px;
  padding-top: 14px;
  border-top: 3px dashed #3a4466;
}

.ref-item {
  background: #181425;
  border: 2px solid #3a4466;
  padding: 4px 2px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.ref-sym {
  font-size: 13px;
  font-weight: bold;
  color: var(--accent-gold);
}

.ref-val {
  font-size: 11px;
  color: var(--text-muted);
}

/* Responsive Layout for small screens */
@media (max-width: 400px) {
  .pixel-card {
    padding: 18px 12px;
  }
  .title {
    font-size: 22px;
  }
  input[type="number"],
  input[type="text"] {
    font-size: 17px;
  }
  .preview-value {
    font-size: 17px;
  }
  .quick-ref {
    grid-template-columns: repeat(4, 1fr);
  }
}

/**
 * Pixel Roman Numeral Converter
 * Standard Subtractive Notation Range: 1 to 3999
 */

const ROMAN_MAP = [
  { value: 1000, numeral: 'M' },
  { value: 900,  numeral: 'CM' },
  { value: 500,  numeral: 'D' },
  { value: 400,  numeral: 'CD' },
  { value: 100,  numeral: 'C' },
  { value: 90,   numeral: 'XC' },
  { value: 50,   numeral: 'L' },
  { value: 40,   numeral: 'XL' },
  { value: 10,   numeral: 'X' },
  { value: 9,    numeral: 'IX' },
  { value: 5,    numeral: 'V' },
  { value: 4,    numeral: 'IV' },
  { value: 1,    numeral: 'I' }
];

// Canonical standard Roman numeral regex (strictly 1 to 3999)
const STRICT_ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

/**
 * Converts an integer (1 to 3999) to its standard Roman numeral representation.
 * Returns 'Not valid' for invalid inputs.
 */
function intToRoman(num) {
  if (typeof num !== 'number' || !Number.isInteger(num) || num < 1 || num > 3999) {
    return 'Not valid';
  }

  let result = '';
  let remaining = num;

  for (let i = 0; i < ROMAN_MAP.length; i++) {
    const entry = ROMAN_MAP[i];
    while (remaining >= entry.value) {
      result += entry.numeral;
      remaining -= entry.value;
    }
  }

  return result;
}

/**
 * Converts a standard Roman numeral string to its integer value.
 * Returns 'Not valid' for non-canonical, malformed, or out-of-range Roman numerals.
 */
function romanToInt(romanStr) {
  if (typeof romanStr !== 'string') {
    return 'Not valid';
  }

  const clean = romanStr.trim().toUpperCase();
  if (clean.length === 0 || !STRICT_ROMAN_REGEX.test(clean)) {
    return 'Not valid';
  }

  const charValues = {
    I: 1,
    V: 5,
    X: 10,
    L: 50,
    C: 100,
    D: 500,
    M: 1000
  };

  let total = 0;
  for (let i = 0; i < clean.length; i++) {
    const currentVal = charValues[clean[i]];
    const nextVal = charValues[clean[i + 1]];

    if (nextVal && currentVal < nextVal) {
      total -= currentVal;
    } else {
      total += currentVal;
    }
  }

  if (total < 1 || total > 3999) {
    return 'Not valid';
  }

  // Round-trip check ensures canonical strict form
  if (intToRoman(total) !== clean) {
    return 'Not valid';
  }

  return total;
}

// DOM Element References
const numberInput = document.getElementById('number-input');
const romanInput = document.getElementById('roman-input');
const numberOutput = document.getElementById('number-output');
const romanOutput = document.getElementById('roman-output');

// Guard flag to prevent mutual event loop ping-pong
let isSyncing = false;

function updateOutputUI(element, value) {
  if (value === 'Not valid') {
    element.textContent = 'Not valid';
    element.className = 'preview-value invalid';
  } else if (value === '' || value === null || value === undefined) {
    element.innerHTML = '&mdash;';
    element.className = 'preview-value empty';
  } else {
    element.textContent = value;
    element.className = 'preview-value';
  }
}

function handleNumberChange() {
  if (isSyncing) return;
  isSyncing = true;

  const rawValue = numberInput.value.trim();

  if (rawValue === '') {
    updateOutputUI(numberOutput, '');
    updateOutputUI(romanOutput, '');
    romanInput.value = '';
    isSyncing = false;
    return;
  }

  const num = Number(rawValue);
  if (!Number.isInteger(num) || num < 1 || num > 3999) {
    updateOutputUI(numberOutput, 'Not valid');
  } else {
    const roman = intToRoman(num);
    updateOutputUI(numberOutput, roman);
    romanInput.value = roman;
    updateOutputUI(romanOutput, num);
  }

  isSyncing = false;
}

function handleRomanChange() {
  if (isSyncing) return;
  isSyncing = true;

  const rawValue = romanInput.value.trim();

  if (rawValue === '') {
    updateOutputUI(romanOutput, '');
    updateOutputUI(numberOutput, '');
    numberInput.value = '';
    isSyncing = false;
    return;
  }

  const convertedNum = romanToInt(rawValue);
  if (convertedNum === 'Not valid') {
    updateOutputUI(romanOutput, 'Not valid');
  } else {
    updateOutputUI(romanOutput, convertedNum);
    numberInput.value = convertedNum;
    updateOutputUI(numberOutput, rawValue.toUpperCase());
  }

  isSyncing = false;
}

// Attach listeners via addEventListener (no inline handlers)
numberInput.addEventListener('input', handleNumberChange);
romanInput.addEventListener('input', handleRomanChange);

// Set initial placeholder values
updateOutputUI(numberOutput, '');
updateOutputUI(romanOutput, '');
